begin;
select set_config('request.jwt.claims', '', true), set_config('request.jwt.claim.sub', '', true);
create temp table _seed_t0 on commit drop as select now() t0;
-- 예전 예시 자료 (가짜 팀원만 있던 일정, 공지, 벌금, 집계). 실제 팀원이 만든 일정(emwoieu2rk1ag 등)과 대화 글은 그대로 둔다
delete from maniball.docs where team_id = '7e57fc00-0000-4000-8000-000000000001' and ((coll = 'events' and id = any(array['e1', 'e2', 'e3', 'e4', 'e5', 'p1', 'p2', 'p3', 'p4', 'p5', 'p6'])) or (coll = 'notices' and id in ('n1', 'n2', 'n3')) or (coll = 'tally' and id in ('mom-p1', 'mom-p2', 'mom-p3', 'mom-p4', 'seen-n1', 'seen-n2', 'seen-n3')) or (coll = 'fines' and (data ->> 'eventId') = any(array['e1', 'e2', 'e3', 'e4', 'e5', 'p1', 'p2', 'p3', 'p4', 'p5', 'p6'])) or coll = 'guestreq');
-- 운영진 본인의 내가 낼 돈에서 지운 예시 일정의 벌금만 뺀다 (다른 기록은 그대로)
update maniball.docs set data = jsonb_set(data, '{fines}', coalesce((select jsonb_agg(f) from jsonb_array_elements(case when jsonb_typeof(data -> 'fines') = 'array' then data -> 'fines' else '[]'::jsonb end) f where not (f ->> 'eventId') = any(array['e1', 'e2', 'e3', 'e4', 'e5', 'p1', 'p2', 'p3', 'p4', 'p5', 'p6'])), '[]'::jsonb)) where team_id = '7e57fc00-0000-4000-8000-000000000001' and coll = 'mydues';
-- 회비: 실제 팀원의 납부 기록은 그대로 두고 가짜 팀원 칸만 더한다
delete from maniball.chat where team_id = '7e57fc00-0000-4000-8000-000000000001' and room in ('sp6', 'su1', 'sp7');
-- 예시를 넣는 동안 생긴 알림은 보내지 않는다 (실제 팀원 휴대폰이 울리지 않게)
delete from maniball.push_outbox where created_at >= (select t0 from _seed_t0);
commit;
select (select count(*) from maniball.members where team_id = '7e57fc00-0000-4000-8000-000000000001') members, (select count(*) from maniball.docs where team_id = '7e57fc00-0000-4000-8000-000000000001') docs, (select count(*) from maniball.chat where team_id = '7e57fc00-0000-4000-8000-000000000001') chat;
